.HeatMap .heatmapHolder .heatmapStatus.--dual-status.status-1::after{background-color:var(--severity-critical)}
.HeatMap .heatmapHolder .heatmapStatus.--dual-status.status-2::after{background-color:var(--severity-trouble)}
.HeatMap .heatmapHolder .heatmapStatus.--dual-status.status-3::after{background-color:var(--severity-attention)}
.HeatMap .heatmapHolder .heatmapStatus.--dual-status.status-4::after{background-color:var(--severity-servicedown)}
.HeatMap .heatmapHolder .heatmapStatus.--dual-status.status-5::after{background-color:var(--severity-clear)}
.HeatMap .heatmapHolder .heatmapStatus.--dual-status.status-6::after{background-color:var(--severity-info)}
