/* Chat container style */
.chat-container {
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    /* background-color: #f4f4f9; */
    z-index: 99;
    position: relative;
}

/* Chat box style */
.chat-box {
    width: 400px;
    height: calc(100vh - 81px);
    background-color: #fff;
    border-radius: 5px;
    box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    position: fixed;
    bottom: 4px;
    right: 4px;
    border-color: red;
    box-shadow:0 0 7px 0 rgba(0, 0, 0, 0.31);
    margin: 10px;
}

