/* FWA Device Score css starts */

.fwa-stat-card{background:#fafafa;border:1px solid #dcdcdc;border-radius:4px;padding:12px 16px;flex:auto;}
.fwa-stat-card__label{font-size:14px;color:#52606B;display:block;font-family: latoBold;}
.fwa-stat-card__label--inline{color:#52606B;}
.fwa-stat-card__value{font-size:20px;font-family:LatoBold;color:#212121;padding-bottom:16px;display:block;border-bottom:1px solid #dcdcdc;margin-bottom:16px}
.fwa-stat-card__value--large{font-size:20px;font-family:latoBold;color:#212121}
.fwa-stat-card__row{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;}
.fwa-stat-card__row-val{font-size:14px;color:#212121;}
.fwa-stat-label-risky{color:#be2b2f}
.fwa-stat-progress-bar{display:flex;height:6px;border-radius:4px;overflow:hidden;gap:2px}
.fwa-stat-progress-bar__seg{height:100%;border-radius:4px;}
.fwa-stat-progress-bar__seg--green,.fwa-stat-dot--green{background:#249C5E;}
.fwa-stat-progress-bar__seg--orange,.fwa-stat-dot--orange{background:#FF9424;}
.fwa-stat-progress-bar__seg--red,.fwa-stat-dot--red{background:#DB3136;}
.fwa-stat-legend{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:14px;color:#4c4c4c;}
.fwa-stat-legend__item{display:flex;align-items:center;gap:4px;}
.fwa-stat-dot{width:8px;height:8px;border-radius:50%;display:inline-block;flex-shrink:0;}
.fwa-stat-cards-row{display:flex;gap:12px;align-items:stretch;}
/* FWA Score Section */
.tab-compact{width:100%;border-bottom:1px solid #dcdcdc;margin-bottom:16px;}
.tab-compact ul{display:flex;gap:20px}
.tab-compact ul li a{padding:10px 0;position:relative;cursor:pointer;font-family:latoBold;font-size:14px;color:#555;text-decoration:none;display:inline-block;}
.tab-compact ul li a.active{color:#1D824E}
.tab-compact ul li a.active:before{content:"";position:absolute;bottom:-1px;left:0;width:100%;height:2px;background:#1D824E;border-radius:2px}
.fwa-score-section{display: flex;flex-direction: column;}
.fwa-score-section-row{display:flex;gap:12px;}
.fwa-score-card{padding:16px 20px;position:relative;border:1px solid #dcdcdc;background:#fff;flex:1;display:flex;flex-direction:column;justify-content:space-between;border-radius:8px;cursor:pointer;}
.fwa-score-card--risky{background:#fff5f5;border-color:#FAD1D3;}
.fwa-score-card--review{background:#fffaf0;border-color:#FFD4A6;}
.fwa-score-card--compliant{background:#f2fbf5;border-color:#ABEDB3;}
.fwa-score-card__hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;}
.fwa-score-card__title{font-size:14px;color:#222;font-family:latoBold}
.fwa-score-badge{font-size:12px;padding:4px 8px;border-radius:2px;display:inline-block;}
.fwa-score-badge--red{background:#DB3136;color:#fff;}
.fwa-score-badge--orange{background:#FF9424;color:#fff;}
.fwa-score-badge--green{background:#25732D;color:#fff;}
.fwa-score-card.active{background:#F9FAFB;border-color:#dcdcdc;border-bottom-right-radius:0;border-bottom-left-radius: 0;}
.fwa-score-card.active:before{content:"";position:absolute;bottom:-16px;left:-1px;width:100%;height:20px;background:#F9FAFB;border-left:1px solid #dcdcdc;border-right:1px solid #dcdcdc}
.fwa-score-body{display:flex;align-items:center;gap:8px;}
.fwa-score-ring{width:40px;height:40px;flex-shrink:0;}
.fwa-score-percent{font-size:32px;font-family: latoBold;color:#222;}
.fwa-score-percent--red{color:#f34848;}
.fwa-score-percent--orange{color:#faad5a;}
.fwa-score-percent--green{color:#27a965;}
.fwa-score-details{background:#F9FAFB;border:1px solid #dcdcdc;padding:24px;margin-top:12px;border-radius:8px;}
.fwa-score-details__row{background:#fff;border:1px solid #e8e8e8;border-radius:4px;padding:14px 16px;margin-bottom:10px;transition:box-shadow 0.3s ease;}
.fwa-score-details__row:hover{box-shadow:0 4px 16px rgba(0,0,0,0.12);}

.fwa-score-details__hdr{display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;position:relative;}
.fwa-score-details__title{font-size:14px;font-family: latoBold;}
.fwa-score-details__desc{font-size:12px;color:#52606B;}
.fwa-score-details__right{display:flex;align-items:center;gap:8px;}
.fwa-score-details-weight{font-size:12px;color:#777;white-space:nowrap;}
.fwa-score-details-score{font-size:20px;padding:4px 12px;border-radius:2px;display:inline-flex;align-items:center;gap:4px;font-family: latoBold;}
.fwa-score-details-score--red{background:#FCE8E9;color:#A02428;}
.fwa-score-details-score--orange{background:#FFF4E9;color:#985814;}
.fwa-score-details-score--green{background:#EAFAEC;color:#25732D;}
.fwa-score-details-bar{width:100%;height:8px;border-radius:4px;background:#e8e8e8;overflow:hidden;}
.fwa-score-details-bar__fill{height:100%;border-radius:4px;}
.fwa-score-details-bar__fill--red{background:#DB3136;}
.fwa-score-details-bar__fill--orange{background:#FF9424;}
.fwa-score-details-bar__fill--green{background:#27AB67;}
.fwa-score-details-legend{display:flex;gap:20px;font-size:12px;color:#555;margin-top:12px}
.fwa-score-details-legend__item{display:flex;align-items:center;gap:5px;}
.fwa-score-details-legend__dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;display:inline-block;}
.fwa-score-details-legend__dot--green{background:#27a965;}
.fwa-score-details-legend__dot--orange{background:#faad5a;}
.fwa-score-details-legend__dot--red{background:#f34848;}
.fwa-score-details-child{margin-top:0px}
.fwa-score-details-table{border:1px solid #E1E5E9;display:flex;flex-direction:column;margin-top:12px;border-radius:4px;}
.fwa-score-details-table > div{display:flex;justify-content:space-between;padding:12px 12px;border-bottom:1px solid #E1E5E9}
.fwa-score-details-table > div:last-child{border-bottom:none;background:#F9FAFB;justify-content: end;gap:8px;font-family:latoBold;}
.fwa-score-card .donut {width: 40px;height: 40px;display: inline-block}
.fwa-score-card .donut__svg {width: 100%;height: 100%;transform: rotate(-90deg)}
.fwa-score-card .donut__track,.fwa-score-card .donut__fill {fill: none;stroke-width: 8}
.fwa-score-card .donut__track {stroke: #ffffff}
.fwa-score-card .donut__fill {stroke-linecap: round;stroke-dasharray: 282.74; transition: stroke-dashoffset 0.6s ease;}
.fwa-score-card--risky .donut__fill{stroke: #f34848;}
.fwa-score-card--review .donut__fill{stroke: #faad5a;}
.fwa-score-card--compliant .donut__fill{stroke: #2BA84A;}
.fwa-score-details__row .fwa-score-details-child{max-height:0;opacity:0;overflow:hidden;transition:max-height 0.4s ease,opacity 0.3s ease;}
.fwa-score-details__row.active .fwa-score-details-child{max-height:500px;opacity:1;margin-top:20px;overflow: auto;}
