.rating-row__slider {-webkit-appearance: none;appearance: none;width: 100%;height: 6px;border-radius: 2px;background: #e0e0e0;outline: none;cursor: pointer;}
.rating-row__slider::-webkit-slider-thumb {-webkit-appearance: none;appearance: none;width: 24px;height: 24px;border-radius: 50%;background: #ffffff;border: 2px solid #2eb872;cursor: pointer;}
