.badge-tag{background:var(--severity-critical-bg);color:var(--severity-critical-text);padding:6px;display:inline-flex;gap:4px;border-radius:36px;align-items:center;font-size:15px;font-weight:700;width:100%;border:1px solid;max-width:50%}
.badge-tag>span{line-height:16px}
.badge-tag.bordered{border-radius:12px;width:auto;padding:3px 6px;border:1px solid;}
.badge-tag.critical{background:var(--severity-critical-bg);color:var(--severity-critical-text);border-color:var(--severity-critical-border)}
.badge-tag.critical > svg{fill:var(--severity-critical-text)}
.badge-tag.trouble{background:var(--severity-trouble-bg);color:var(--severity-trouble-text);border-color:var(--severity-trouble-border)}
.badge-tag.trouble > svg{fill:var(--severity-trouble)}
.badge-tag.attention{background:var(--severity-attention-bg);color:var(--severity-attention-text);border-color:var(--severity-attention)}
.badge-tag.attention > svg{fill:var(--severity-attention-text)}
.badge-tag.servicedown{background:var(--severity-servicedown-bg);color:var(--severity-servicedown-text);border-color:var(--severity-servicedown-border)}
.badge-tag.servicedown > svg{fill:var(--severity-servicedown)}
.badge-tag.up{background:var(--severity-up-bg);color:var(--severity-up-text);border-color:var(--severity-up-border)}
.badge-tag.up > svg{fill:var(--severity-up)}
.badge-tag.down{background:var(--severity-down-bg);color:var(--severity-down-text);border-color:var(--severity-down-border)}
.badge-tag.down > svg{fill:var(--severity-down)}
.badge-tag.clear{background:var(--severity-clear-bg);color:var(--severity-clear-text);border-color:var(--severity-clear-border)}
.badge-tag.clear > svg{fill:var(--severity-clear)}
.badge-tag.info{background:var(--severity-info-bg);color:var(--severity-info-text);border-color:var(--severity-info-border)}
.badge-tag.info > svg{fill:var(--severity-info)}
.badge-tag.unmanaged{background:var(--severity-unmanaged-bg);color:var(--severity-unmanaged-text);border-color:var(--severity-unmanaged-border)}
.badge-tag.unmanaged > svg{fill:var(--severity-unmanaged)}
.badge-tag.notmonitored{background:var(--severity-notmonitored-bg);color:var(--severity-notmonitored-text);border-color:var(--severity-notmonitored-border)}
.badge-tag.notmonitored > svg{fill:var(--severity-notmonitored)}
