.DI-Header__back-btn .title-with-breadcrumbcard li a{color:#2E64B8 !important;padding:0 !important;line-height:normal;pointer-events: auto;opacity:.7;transition: .3s ease-in;max-width: 250px;}
.DI-Header__back-btn .title-with-breadcrumbcard li a:hover{opacity:1;transition: .3s ease-in;}
.DI-Header__back-btn .title-with-breadcrumbcard li a:before{display:none !important}

