/* AI Setting */
.aiSettingsStatusRegion{max-width:1180px;clear:both;margin-bottom:16px}
.aiSettingsLoading{position:fixed;top:50%;left:50%;transform:translate(-50%,-50%)}
.aiSettingsStaleWarning{display:flex;align-items:flex-start;gap:16px;box-sizing:border-box;width:100%;padding:12px 16px;border:1px solid #f4c36a;border-radius:4px;background:#fff9ec;color:#6f4b00;text-align:left}
.aiSettingsStaleContent{flex:1 1 auto;min-width:0;overflow-wrap:anywhere}
.aiSettingsStaleContent p{margin:0 0 8px}
.aiSettingsStaleContent ul{display:grid;margin:0;padding:0;border-top:1px solid #eadfca;list-style:none}
.aiSettingsStaleRow{display:flex;align-items:baseline;gap:12px;padding:6px 0;border-bottom:1px solid #eadfca}
.aiSettingsStaleOwner{flex:0 0 180px;min-width:0;font-weight:600;color:#4d5966}
.aiSettingsStaleModels{display:flex;flex:1 1 auto;flex-wrap:wrap;align-items:center;gap:6px;min-width:0}
.aiSettingsStaleModel{min-width:0;padding:2px 6px;border:1px solid #e4d8c0;border-radius:3px;background:rgba(255,255,255,.55);color:#596574;overflow-wrap:anywhere}
.aiSettingsStaleNewModel{font-weight:600;color:#374151}
.aiSettingsStaleArrow{color:#8a744d}
.aiSettingsStaleActions{display:flex;flex:0 0 auto;gap:8px;align-items:center}
.aiSettingsStaleActions .opmBtn{float:none;margin:0;white-space:nowrap}
.aiSettingsForm{max-width:1180px;clear:both;float:left;width:100%;position:relative}
.aiSettingsTable{border:1px solid #e3e6ea;border-radius:4px;background:#fff;overflow:hidden}
.aiSettingsRow{display:flex;flex-wrap:wrap;align-items:center;gap:18px}
.aiSettingsParentRow{padding:12px 18px;background:#f5f7fa;border-bottom:1px solid #e3e6ea}
.aiSettingsFeatureRow{padding:10px 18px;border-bottom:1px solid #eef0f3}
.aiSettingsFeatureRow.parentDisabled{opacity:.5;filter:alpha(opacity=50);position:relative}
.aiSettingsFeatureRow.parentDisabled:before{content:'';position:absolute;top:0;right:0;bottom:0;left:0;z-index:9}
.aiSettingsFeatureRow.parentDisabled .select2-container--disabled{opacity:1 !important;filter:alpha(opacity=100)}
.aiSettingsTitleCell{flex:1 1 auto;min-width:160px;font-weight:600;color:#2b323b}
.aiSettingsFeatureTitleCell{flex:1 1 auto;min-width:160px;color:#374151}
.aiSettingsToggleCell{flex:0 0 auto;white-space:nowrap;display:flex;gap:6px}
.aiSettingsAttrCell{flex:0 0 auto;display:flex;align-items:center;gap:6px}
.aiSettingsAttrLabel{display:inline-block;width:100px;font-size:12px;color:#6b7785;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:right}
.aiSettingsSelect,.aiSettingsTable .aiSettingsAttrCell .select2-container{flex:0 0 200px;width:200px !important;min-width:200px;max-width:200px}
.aiSettingsCascadeCell{flex:0 0 24px}
.aiSettingsCascadeCell,.aiSettingsCascadeCheckBox,.aiSettingsCascadeCheckBox label{width:24px;height:35px}
.aiSettingsCascadeCheckBox > div{float:none;min-width:24px;min-height:35px;padding:0}
.aiSettingsCascadeCheckBox input{width:24px}
.aiSettingsCascadeCheckBox input:disabled{cursor:not-allowed}
.aiSettingsCascadeCheckBox label{display:block;line-height:normal}
.aiSettingsCascadeCheckBox label:before{left:0}
.aiSettingsCascadeCheckBox label:after{left:5px}
.aiSettingsActions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px;width:100%;padding-top:14px}
.aiSettingsErrorState{max-width:1180px;display:flex;align-items:center;gap:12px;padding:12px 16px;border:1px solid #f4a18f;border-radius:4px;background:#fff4f1;color:#a33a24;margin:25px 30px 0}
.aiSettingsErrorMessage{flex:1;min-width:0}
@media (max-width:768px){.aiSettingsStaleWarning{flex-direction:column}.aiSettingsStaleRow{display:block}.aiSettingsStaleOwner{display:block;margin-bottom:4px}.aiSettingsStaleActions{flex-wrap:wrap;align-self:flex-end}}
/* AI Settings end */